"""Generates DEMO_EVIDENCE_MANIFEST.md from the ledger, the frozen manifests and the snapshot manifest (no hand-typed hashes)."""
import json, pathlib, subprocess, sys
HERE = pathlib.Path(__file__).resolve().parent; WS = HERE.parent
led = json.loads((WS / "dp001/ai_findings.json").read_text()); snap = json.loads((HERE / "DEMO_SNAPSHOT_MANIFEST.json").read_text())
fz = json.loads((WS / "spatial_plan/FROZEN_TEST003.json").read_text()); a = led["accounting"]
L = ["# DEMO_EVIDENCE_MANIFEST — authentic AMD results and source hashes\n", "Generated by `demo/make_evidence_manifest.py` from the stored ledger and manifests. Every AI-performance claim in the demo rests ONLY on the REAL rows below. The two simulated items are excluded from every claim.\n",
     "## Source identities\n", f"* Source drawing `dp001_ansi_b_v2_drawings` SHA-256 `{snap['key_hashes']['source_pdf_ansi_b']}`", f"* Rate-book workbook SHA-256 `{snap['key_hashes']['workbook']}` (pinned; unchanged)",
     f"* AI findings ledger `dp001/ai_findings.json` SHA-256 `{snap['key_hashes']['dp001/ai_findings.json']}`",
     f"* Frozen Spatial Test 003 plan SHA-256 `{fz['plan_sha256']}`", f"* `LIVE_CALLS_DISABLED` hold file SHA-256 `{snap['key_hashes']['LIVE_CALLS_DISABLED']}` (in force; no AMD request in this build or in any rehearsal)",
     f"* Snapshot: {len(snap['source_files'])} source files hashed in `demo/DEMO_SNAPSHOT_MANIFEST.json`; frozen AMD evidence files re-verified: {snap['frozen_files_checked']} (all match: {snap['frozen_amd_evidence_all_match']})\n",
     "## Real AMD inference attempts (previously recorded; replayed offline)\n", "| Attempt | Model | Document (sha256) | Outcome | Input crop sha256 | Accepted output |", "|---|---|---|---|---|---|"]
for x in led["attempts"]:
    L.append(f"| `{x['attempt_id']}` | {x['model']} | `{x['document']['doc_id']}` `{x['document']['sha256'][:16]}…` | {x['state'].replace('_', ' ')} | `{(x.get('input_sha256') or 'n/a')[:16]}{'…' if x.get('input_sha256') else ''}` | {x['accepted_output']} |")
L += ["", "Spatial Test 003 attempts (frozen, plan `784c93c8…`): " + "; ".join(f"`{x['attempt_id']}` raw `{x['artifacts'][0]['sha256'][:16]}…` {x['request_started_utc']} tokens {x['usage']['prompt_tokens']}/{x['usage']['completion_tokens']} ${x['usage']['cost_usd']:.6f}" for x in led["attempts"] if x["attempt_id"].startswith("spatial_003_")) + "\n",
      "## What the findings are (counts from the ledger)\n", f"* Real findings {a['real_findings']} ({a['real_on_ansi_b_native']} native ANSI B, {a['real_on_34x22_origin']} captured on a different 34×22 file); simulated {a['simulated_findings']} (none ship; simulated fixtures live only in test files).",
      f"* Verified text on its origin document: {a['real_text_verified_on_origin']} of 14 (only {a['real_34x22_corroborated_on_ansi_b_text']} also appears on the ANSI B sheet). Spatial: {a['spatial_observations']} observations of {a['spatial_distinct_relationships']} distinct relationships.",
      f"* Classification counts: `{json.dumps(a['classification_counts'])}`", "* **Not all 32 real findings are verified.** Gate label localization scored 7/7 checks (localization only); gate-symbol relationships verified: 0; type-tag leaders: 1 confirmed (A), 1 contradicted twice (B, model said “clear”); keynote 6 a false candidate; Spatial Test 003's predefined success criterion was NOT MET.\n",
      "## The money-shot finding (authentic, not simulated)\n"]
b = next(f for f in led["findings"] if f["finding_id"] == "AMD-spatial003-N-type_tag-B"); L += [f"* `{b['finding_id']}` — provenance `{b['provenance']}`, run `{b['run']['run_id']}`, model {b['model']['requested']}, crop `{b['run']['input_sha256'][:16]}…`, claim “{b['claim']['text']}”, model confidence `{b['uncertainty']['model_stated']}`, classification **{b['classification']}**, vector oracle: leader ends on `{b['evidence']['vector_anchor']['terminal_element']}` ({b['evidence']['vector_anchor']['distance_in']} sheet-in). Same relationship contradicted in Test 002 (`AMD-spatial002-4-fence_type_tag-B-top`). Accept → API `409 CONTRADICTED_BY_DRAWING_EVIDENCE`.\n", "## Execution-control note\n", f"* {led['execution_control_deviations'][0]['id']}: {led['execution_control_deviations'][0]['what_happened']} {led['execution_control_deviations'][0]['decision']}\n"]
(HERE / "DEMO_EVIDENCE_MANIFEST.md").write_text("\n".join(L)); print("written", len("\n".join(L)))
